// One item per roll, so the HTTP node below asks the lab about one order at a time.
return ($input.first().json.items ?? []).map((roll) => ({
  json: { rollId: roll.id, orderId: roll.labOrderId, status: roll.status },
}));

// The shape of a real dm order, confirmed 2026-09-23 against
// spot.photoprintit.com/spotapi/orderInfo/forShop:
//
//   summaryStateCode  "PROCESSING"                     <- machine readable, this is what we use
//   summaryStateText  "Dein Auftrag wird gefertigt."   <- for the mail
//   summaryDate       "2026-09-21"
//   deliveryType/Text 0 + the dm branch address        <- 0 = collect in the store
//   subOrders[0]      the same state plus trackingNumber/trackingUrl once something ships
//
// The download link for the digital images is *not* in here - it arrives by mail, which is what
// the other branch of this workflow waits for.
const info = $input.first().json;
const roll = $('One roll at a time').first().json;
const sub = Array.isArray(info.subOrders) ? info.subOrders[0] : undefined;

const code = String(info.summaryStateCode ?? sub?.stateCode ?? '').toUpperCase();
// Everything the lab reports while it is still working on the order. Anything else - shipped,
// ready for pickup, done - is worth a mail. Unknown codes count as "worth a look" on purpose:
// a new code should reach you, not be swallowed.
const IN_PROGRESS = new Set(['', 'NEW', 'RECEIVED', 'ORDERED', 'PROCESSING', 'IN_PRODUCTION']);

return [
  {
    json: {
      ...roll,
      finished: !IN_PROGRESS.has(code),
      code,
      stateText: info.summaryStateText ?? sub?.stateText ?? code,
      stateDate: info.summaryDate ?? sub?.stateDate ?? null,
      delivery: info.deliveryText ?? '',
      trackingUrl: sub?.trackingUrl ?? null,
      trackingNumber: sub?.trackingNumber ?? null,
    },
  },
];
